/**
 * lib/chunker.mjs —— 切块（与寻枝 0.3.1 完全一致：1200 字 / 80 字重叠）
 *
 * 来源：dsh-semantic-recall 0.3.1 `lib/chunk.mjs`（同作者）。
 * 块是检索的物理单位，不是记忆的最小单位；记忆最小单位是一条 utterance。
 */

export function chunkText(text, size = 1200, overlap = 80) {
  const t = String(text || '').trim()
  if (!t) return []
  if (t.length <= size) return [t]
  const out = []
  let i = 0
  while (i < t.length) {
    out.push(t.slice(i, i + size))
    i += size - overlap
  }
  return out
}

/** 抽取记录 → 原始块（带锚点） */
export function buildChunks(recs, size = 1200, overlap = 80) {
  const chunks = []
  for (const r of recs) {
    const parts = chunkText(r.text, size, overlap)
    parts.forEach((p, i) => {
      chunks.push({
        session: r.session,
        ws: r.ws,
        wsPretty: r.wsPretty,
        t: r.t,
        role: r.role,
        part: i,
        text: p,
        sourceType: r.sourceType || (r.role === 'user' ? 'user' : 'assistant'),
        msgId: r.msgId || null,
        seq: r.seq ?? null,
      })
    })
  }
  return chunks
}

/** 旧增量口径的块指纹（保持与寻枝一致，便于对账） */
export function chunkKey(c) {
  return `${c.session}|${c.role}|${c.t}|${c.part}`
}
